window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fe28813b86648103"]={"versions": [{"id": "FIG-fe28813b86648103", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Constraints im Kontext der AUTOSAR Timing Extensions (<code>AUTOSAR_TPS_TimingExtensions</code>). Dargestellt ist die Metamodell-Struktur der Klasse <code>SynchronizationPointConstraint</code>, abgeleitet von <code>TimingConstraint</code>, und deren strukturelle Verknüpfungen zu Quell- und Zielreferenzen für Ausführungsreihenfolgen und Ereignisse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Klassen und vier gerichtete Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>SynchronizationPointConstraint</code> (Spezialisierung von <code>TimingConstraint</code>): Zentrales Metamodellelement zur Festlegung von Synchronisationspunkten.\n</li><li><code>EOCExecutableEntityRefGroup</code> (qualifiziert über <code>ExecutionOrderConstraint::</code>, abgeleitet von <code>EOCExecutableEntityRefAbstract</code>): Gruppierung von Referenzen auf ausführbare Entitäten im Rahmen von Ausführungsreihenfolgen-Bedingungen.\n</li><li><code>AbstractEvent</code> (qualifiziert über <code>InternalBehavior::</code>, abgeleitet von <code>Identifiable</code>): Abstraktes Verhaltenselement, das als Referenzpunkt für auslösende oder zu synchronisierende Ereignisse dient.\n</li></ul>\n<p class=\"fig-p\">Assoziationen (jeweils unidirektional von <code>SynchronizationPointConstraint</code> ausgehend):</p>\n<ul class=\"fig-list\"><li><code>+sourceEec</code>: Multiplizität <code>0..*</code> zu <code>ExecutionOrderConstraint::EOCExecutableEntityRefGroup</code>\n</li><li><code>+targetEec</code>: Multiplizität <code>0..*</code> zu <code>ExecutionOrderConstraint::EOCExecutableEntityRefGroup</code>\n</li><li><code>+sourceEvent</code>: Multiplizität <code>0..*</code> zu <code>InternalBehavior::AbstractEvent</code>\n</li><li><code>+targetEvent</code>: Multiplizität <code>0..*</code> zu <code>InternalBehavior::AbstractEvent</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Semantik. Es spezifiziert Deklarationsstrukturen, mit denen zur Entwurfs- bzw. Konfigurationszeit Synchronisationsbeziehungen zwischen Quell- (<code>sourceEec</code>, <code>sourceEvent</code>) und Zielpunkten (<code>targetEec</code>, <code>targetEvent</code>) auf Ebene von ausführbaren Entitäten und internen Verhaltensereignissen definiert werden können.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Vorgabe für AUTOSAR Timing Extensions. Ein <code>SynchronizationPointConstraint</code> erfordert konsistente Referenzierung kompatibler Quell- und Zielelemente. Da alle vier Rollen mit Kardinalität <code>0..*</code> modelliert sind, erlaubt das Metamodell flexible Konstellationen (z. B. reine Event-Synchronisation, reine EEC-Synchronisation oder hybride Verknüpfungen). Modellierer müssen sicherstellen, dass referenzierte Ereignisse und Entity-Gruppen im jeweiligen Komponenten- oder Systemkontext auflösbar sind.</p>"}, {"id": "FIG-477aa107bf50000b", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Constraints im Kontext der AUTOSAR Timing Extensions (<code>AUTOSAR_TPS_TimingExtensions</code>). Dargestellt ist die Metamodell-Struktur der Klasse <code>SynchronizationPointConstraint</code>, abgeleitet von <code>TimingConstraint</code>, und deren strukturelle Verknüpfungen zu Quell- und Zielreferenzen für Ausführungsreihenfolgen und Ereignisse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Klassen und vier gerichtete Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>SynchronizationPointConstraint</code> (Spezialisierung von <code>TimingConstraint</code>): Zentrales Metamodellelement zur Festlegung von Synchronisationspunkten.\n</li><li><code>EOCExecutableEntityRefGroup</code> (abgeleitet von <code>EOCExecutableEntityRefAbstract</code>): Gruppierung von Referenzen auf ausführbare Entitäten im Rahmen von Ausführungsreihenfolgen-Bedingungen.\n</li><li><code>AbstractEvent</code> (abgeleitet von <code>Identifiable</code>): Abstraktes Verhaltenselement, das als Referenzpunkt für auslösende oder zu synchronisierende Ereignisse dient.\n</li></ul>\n<p class=\"fig-p\">Assoziationen (jeweils unidirektional von <code>SynchronizationPointConstraint</code> ausgehend):</p>\n<ul class=\"fig-list\"><li><code>+sourceEec</code>: Multiplizität <code>0..*</code> zu <code>EOCExecutableEntityRefGroup</code>\n</li><li><code>+targetEec</code>: Multiplizität <code>0..*</code> zu <code>EOCExecutableEntityRefGroup</code>\n</li><li><code>+sourceEvent</code>: Multiplizität <code>0..*</code> zu <code>AbstractEvent</code>\n</li><li><code>+targetEvent</code>: Multiplizität <code>0..*</code> zu <code>AbstractEvent</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Semantik. Es spezifiziert Deklarationsstrukturen, mit denen zur Entwurfs- bzw. Konfigurationszeit Synchronisationsbeziehungen zwischen Quell- (<code>sourceEec</code>, <code>sourceEvent</code>) und Zielpunkten (<code>targetEec</code>, <code>targetEvent</code>) auf Ebene von ausführbaren Entitäten und internen Verhaltensereignissen definiert werden können.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Vorgabe für AUTOSAR Timing Extensions. Ein <code>SynchronizationPointConstraint</code> erfordert konsistente Referenzierung kompatibler Quell- und Zielelemente. Da alle vier Rollen mit Kardinalität <code>0..*</code> modelliert sind, erlaubt das Metamodell flexible Konstellationen (z. B. reine Event-Synchronisation, reine EEC-Synchronisation oder hybride Verknüpfungen). Modellierer müssen sicherstellen, dass referenzierte Ereignisse und Entity-Gruppen im jeweiligen Komponenten- oder Systemkontext auflösbar sind.</p>"}], "trans": [{"from": "FIG-fe28813b86648103", "to": "FIG-477aa107bf50000b", "fr": "R20-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>In der linken Klasse wurde das Namespace-Präfix <code>ExecutionOrderConstraint::</code> vor <code>EOCExecutableEntityRefGroup</code> entfernt.\n</li><li>In der rechten Klasse wurde das Namespace-Präfix <code>InternalBehavior::</code> vor <code>AbstractEvent</code> entfernt.\n</li></ul>"}]};
